<script setup>
import { ref, onMounted, watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowLeft, ArrowUpRight, CalendarDays, ShieldCheck, PackageCheck } from 'lucide-vue-next'
import { api,session,money,today,tomorrow } from '../api'
import { consultEquipment } from '../assistant'
import { validateRentalDates } from '../rental-dates'
const route=useRoute(),router=useRouter(), item=ref(null),loading=ref(true),error=ref(''),quote=ref(null),quoteBusy=ref(false),quoteError=ref(''),booking=ref(false),bookingError=ref(''),startDate=ref(String(route.query.startDate||today())),endDate=ref(String(route.query.endDate||tomorrow())),remark=ref('')
let quoteVersion=0,requestId=null
watch([startDate,endDate],()=>{quoteVersion++;quote.value=null;quoteError.value='';requestId=null})
watch(remark,()=>{requestId=null})
onMounted(async()=>{try{item.value=await api(`/equipment/${route.params.id}`)}catch(e){error.value=e.message}finally{loading.value=false}})
async function getQuote(){const current=++quoteVersion;quoteBusy.value=true;quoteError.value='';quote.value=null;try{validateRentalDates(startDate.value,endDate.value);const result=await api(`/equipment/${route.params.id}/quote`,{query:{startDate:startDate.value,endDate:endDate.value}});if(current===quoteVersion)quote.value=result}catch(e){if(current===quoteVersion)quoteError.value=e.message}finally{quoteBusy.value=false}}
async function book(){if(!session('USER'))return router.push({path:'/login',query:{redirect:route.fullPath}});if(!quote.value||!quote.value.availableCount)return;booking.value=true;bookingError.value='';try{requestId ||= globalThis.crypto?.randomUUID?.()||`web-${Date.now()}-${Math.random().toString(36).slice(2)}`;const order=await api('/orders',{method:'POST',body:{equipmentId:Number(route.params.id),startDate:startDate.value,endDate:endDate.value,requestId,remark:remark.value}});router.push({path:'/orders',query:{id:order.id,created:'1'}})}catch(e){bookingError.value=e.message}finally{booking.value=false}}
</script>
<template><section class="wrap detail-page"><RouterLink to="/" class="back-link"><ArrowLeft :size="16"/>返回器材目录</RouterLink><div v-if="loading" class="state">正在加载器材…</div><div v-else-if="error" class="state error">{{error}}</div><div v-else-if="item" class="detail-grid"><div><div class="detail-photo"><span class="category-label">{{item.categoryName}}</span><img :src="item.image||'/illustrations/camera.svg'" :alt="item.name" @error="$event.target.src='/illustrations/camera.svg'"></div><div class="detail-description"><span class="eyebrow">ABOUT THIS GEAR</span><h2>器材说明与配置</h2><p>{{item.description||'暂无详细介绍，欢迎联系门店了解器材。'}}</p><div class="mini-benefits"><span><ShieldCheck :size="18"/>独立资产管理</span><span><PackageCheck :size="18"/>到店交接验收</span></div></div></div><div class="booking-panel"><span class="eyebrow">{{item.brand||'GEARHUB COLLECTION'}}</span><h1>{{item.name}}</h1><div class="detail-price"><strong>¥{{money(item.dailyRate)}}</strong><span>/ 天</span></div><p class="muted">押金 ¥{{money(item.deposit)}} · 到店办理</p><button class="plain-link consult-link" @click="consultEquipment(item,startDate,endDate)">咨询这款器材</button><hr><h3><CalendarDays :size="18"/>租期与费用</h3><form @submit.prevent="getQuote"><div class="form-grid"><label>领取日期<input type="date" v-model="startDate" :min="today()" required :disabled="booking"></label><label>归还日期<input type="date" v-model="endDate" :min="startDate" required :disabled="booking"></label></div><p class="hint">领取日计费，归还日不计费。例如 1 日至 3 日为 2 天；最长 30 天。</p><button class="button secondary full" :disabled="quoteBusy||booking">{{quoteBusy?'正在查询…':'查看可租数量与报价'}}</button></form><p v-if="quoteError" class="alert error" role="alert">{{quoteError}}</p><div v-if="quote" class="quote-box"><div class="availability" :class="{ unavailable:!quote.availableCount }"><span class="live-dot"/>{{quote.availableCount?`当前可租 ${quote.availableCount} 件`:'所选日期暂无可租器材'}}</div><dl><div><dt>租金 · {{quote.rentalDays}} 天</dt><dd>¥{{money(quote.rentalAmount)}}</dd></div><div><dt>押金</dt><dd>¥{{money(quote.depositAmount)}}</dd></div><div class="quote-total"><dt>到店应办理金额</dt><dd>¥{{money(quote.totalAmount)}}</dd></div></dl><p class="hint">报价不锁定库存，提交预约时会再次确认可租情况。</p><label>预约备注（选填）<textarea v-model="remark" maxlength="255" placeholder="例如：用于人像拍摄，需要了解操作方法" :disabled="booking"/></label><p v-if="bookingError" class="alert error" role="alert">{{bookingError}}</p><button class="button lime full" :disabled="booking||!quote.availableCount" @click="book">{{booking?'正在提交…':session('USER')?'提交预约':'登录后预约'}}<ArrowUpRight :size="19"/></button></div><p class="booking-note">本平台不提供线上支付。提交后请等待门店确认，到店领取时办理租金及押金交接。</p></div></div></section></template>
